import QRCode from "qrcode";

/**
 * Server-side QR code as an inline SVG string. Only https links are encoded, so the SVG
 * (generated by the qrcode library, not by CMS input) is safe to inline.
 */
export async function qrSvg(url) {
  if (typeof url !== "string" || !/^https:\/\/[^\s<>"']+$/i.test(url.trim())) return null;
  try {
    return await QRCode.toString(url.trim(), {
      type: "svg",
      margin: 1,
      errorCorrectionLevel: "M",
      color: { dark: "#111111", light: "#ffffff" },
    });
  } catch {
    return null;
  }
}
